  function progressRecords(personId,courseId,version){const all=D().state.learners?.[personId]?.courses||{};return Object.entries(all).filter(([id])=>!courseId||id===courseId).flatMap(([id,p])=>[p,...(p.versionHistory||[])].filter(x=>version==null||versionKey(x.materialVersion??x.courseVersion??D().state.catalog?.find(c=>c.id===id)?.version)===versionKey(version)).map(x=>({...x,courseId:id})));}
  function allAttempts(personId,courseId,version){const seen=new Set();return progressRecords(personId,courseId,version).flatMap(p=>p.attempts||[]).filter((a,i)=>{const key=a.id||JSON.stringify([a.courseId,a.courseVersion,a.submittedAt,a.answers,i]);if(seen.has(key))return false;seen.add(key);return true;});}
  function answerCorrect(q,answer){if(window.LearningUI?.evaluateAnswer)return window.LearningUI.evaluateAnswer(q,answer);const type=q.type||'single';if(type==='short'){const norm=x=>String(x??'').replace(/\s/g,'').toLowerCase();return(q.acceptedAnswers||[]).some(x=>norm(x)===norm(answer));}if(type==='multiple'){const norm=x=>[...new Set(Array.isArray(x)?x.map(Number):[])].sort((a,b)=>a-b);return JSON.stringify(norm(answer))===JSON.stringify(norm(q.answer));}return answer!==null&&answer!==undefined&&Number(answer)===Number(q.answer);}
  function dateOf(value){const m=String(value||'').match(/^(\d{4})[/-](\d{1,2})[/-](\d{1,2})/);return m?m[1]+'-'+m[2].padStart(2,'0')+'-'+m[3].padStart(2,'0'):'';}
  function weaknessStats(personId,category,days=90){let total=0,correct=0,attemptCount=0;for(const a of allAttempts(personId)){const date=dateOf(a.submittedAt||a.at),age=daysBetween(simulationDate(person(personId).businessLine),date);if(!date||age<0||age>days)continue;let included=false;(a.questions||[]).forEach((q,i)=>{const c=window.LearningUI.getCourse(a.courseId),src=CategoryTree.source(c,q);if(q.category===category||src.categoryPaths.includes(category)||src.categoryIds.some(id=>CategoryTree.within(id,category))){total++;correct+=answerCorrect(q,a.answers?.[i])?1:0;included=true;}});if(included)attemptCount++;}return{category,total,correct,wrong:total-correct,attemptCount,errorRate:total?(total-correct)/total*100:0};}
  function taskComplete(a){return complete(a)||a.type==='course'&&!a.reinforcement&&progressRecords(a.person,a.courseId,a.version).some(p=>p.passed);}
