  function metrics(a){return window.LearningUI?.getLearningMetrics?.(a.courseId,a.person,a.version)||{};}
  function canPublish(c){return canReview()||role()==='branch'&&courseAllowed(c)&&c.ownerBranch===myBranch();}
  function policyPanel(){const p=policyFor(),edit=role()==='business'||sys();return `<details class="adm-policy"><summary>${esc(myLine())}新人期間示例（待確認） · ${p.months} 個曆月</summary><p class="small muted">依到職日推算至第 ${p.months} 個月同日，新人期間待確認；期滿行為待確認，目前僅呈現日期推算的示範標示。手動標籤獨立保留；每次初始化與人員資料變更時重算並自動執行啟用的新人規則。</p><div class="adm-filter-grid"><label class="field">新人期間<select id="policy-months" ${edit?'':'disabled'}>${[3,6].map(n=>`<option value="${n}" ${Number(p.months)===n?'selected':''}>${n} 個曆月</option>`).join('')}</select></label><label class="field">模擬日期<input id="policy-date" type="date" value="${esc(p.simulationDate)}" ${edit?'':'disabled'}></label></div>${edit?button('模擬執行到所選日期','adm-policy-save','secondary adm-full'):''}</details>`;}

  function scopedFilter(people,{branch,department,major,tag,search,joinFrom,joinTo}={}){return people.filter(p=>(!branch||branch==='all'||p.branch===branch)&&(!department||department==='all'||p.department===department)&&(!major||major==='all'||majorFor(p)===major)&&(!tag||tag==='all'||allTags(p).includes(tag))&&(!search||[p.name,p.account,p.employeeNo,p.counter,p.departmentNumber].join(' ').toLowerCase().includes(search.toLowerCase()))&&(!joinFrom||p.joinDate&&p.joinDate>=joinFrom)&&(!joinTo||p.joinDate&&p.joinDate<=joinTo));}
  function options(arr,selected,all='全部'){return (all?`<option value="all" ${selected==='all'?'selected':''}>${all}</option>`:'')+arr.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('');}
  function filterFields(prefix,filters={},includeTag=true){const ppl=scopePeople(),historical=prefix==='tracking',orgs=historical?scopeAssignments().map(trainingOrg):ppl.map(p=>({...p,departmentMajor:majorFor(p)}));return `<div class="adm-filter-grid"><label class="field">${historical?'受訓時':''}分公司<select id="${prefix}-branch">${options([...new Set(orgs.map(p=>p.branch))],filters.branch||'all','全部分公司')}</select></label><label class="field">${historical?'受訓時':''}部門<select id="${prefix}-department">${options([...new Set(orgs.filter(p=>!filters.branch||filters.branch==='all'||p.branch===filters.branch).map(p=>p.department))],filters.department||'all','全部部門')}</select></label><label class="field">部別大類（部號首碼）<select id="${prefix}-major">${options([...new Set(orgs.map(p=>p.departmentMajor))],filters.major||'all','全部大類')}</select></label>${includeTag?`<label class="field">目前人員／專櫃標籤<select id="${prefix}-tag">${options([...new Set(ppl.flatMap(allTags))],filters.tag||'all','全部標籤')}</select></label>`:''}</div><p class="adm-map-note">首碼對應僅為示例：1 女裝、2 男童裝、3 化妝品、4 餐飲；並非正式 13 大類，待遠百提供對照。部號與唯一部門代碼分開。</p>`;}
  function roleMatrix(){return `<details class="card"><summary>角色、範圍與上架路徑（示例）</summary><p class="small">財務與 HR 同層，按各自業務線／分店分開資料。最高管理者寫入權待決；目前展示唯讀。分店分類維護權待確認。</p><div class="matrix-scroll"><table><thead><tr><th>角色</th><th>部門範圍</th><th>動作</th></tr></thead><tbody><tr><td>分店財務／HR</td><td>本店 × 所屬業務線</td><td>草稿、送審；已核准後上架</td></tr><tr><td>財務／HR 業管</td><td>所屬業務線 × 跨店</td><td>直接上架或審核（不可自審）</td></tr><tr><td>最高管理者</td><td>跨單位</td><td>展示唯讀；寫入權待決</td></tr><tr><td>system 系管</td><td>共用主檔</td><td>人員／帳號／GPS／裝置；不查學習內容</td></tr></tbody></table></div><p class="small muted">一期 RWD；既有 App 整合與自動化執行留待後續，原生／WebView 未定。此矩陣為本機示例，不是正式授權契約。</p></details>`;}
  function emailPreview(){return `<details class="card" open><summary>派課 Email 樣稿與狀態（示例）</summary><p class="small">主旨：【遠百學習】新課程指派：收銀結帳與異常處理<br>您好，請於指定期限前開啟課程並完成教材與測驗。<br>課程連結：<a href="#course" data-go="course" data-course="cash">開啟課程</a></p><p class="small muted">未登入收信者需先登入；只展示樣稿，不寄信。正式寄信通道與提醒頻率待確認。</p><div class="adm-simple-row"><span>學員 A · learner.a@example.invalid</span>${badge('待寄（示例）')}</div><div class="adm-simple-row"><span>學員 B · 未提供地址</span>${badge('缺 Email','warn')}</div><div class="adm-simple-row"><span>員工 D · employee.d@example.invalid</span>${badge('失敗（示例：傳輸未啟用）','warn')}</div></details>`;}
  function dashboard(){if(sys())return header('共用模組 · 系統管理','管理帳號與館別設定，學習內容與成績不在此角色的可閱範圍。')+`<div class="adm-list">${nav('accounts','帳號匯入與檢核','users')}${nav('people','人員、組織與標籤','users')}${nav('gps-admin','館別 GPS 設定','map')}${nav('devices','登入裝置紀錄','shield')}${nav('audit','系統操作紀錄','file')}</div>`;
    const a=scopeAssignments(),done=a.filter(complete).length,late=a.filter(overdue).length,pendingReview=scopeCourses().filter(c=>c.status==='待審核').length;
    return roleMatrix()+header(myLine()+'訓練管理','學習、派發與閱讀確認，在同一個工作台完成。')+`<section class="adm-hero"><span>今日追蹤</span><h3>${a.length-done}<small> 項待完成</small></h3><p>${late} 項逾期 · ${pendingReview} 份課程待審核</p>${button('查看派發追蹤 '+icon('arrow'),'adm-nav','primary','data-view="tracking"')}</section><div class="adm-stats"><div><strong>${scopePeople(true).length}</strong><span>啟用人員</span></div><div><strong>${a.length?Math.round(done/a.length*100):0}%</strong><span>完成／簽收</span></div><div><strong>${scopeCourses().filter(c=>c.status==='已上架').length}</strong><span>已上架課程</span></div></div><h3 class="section-title">學習管理</h3><div class="adm-list">${nav('assign','派課與公告派發','users')}${nav('auto-assign','新人與弱項派課規則','chart')}${nav('tracking','派發追蹤與報表','chart')}${nav('catalog','課程分類與版本','book')}${nav('review','課程審核與上架','check')}${nav('notices-management','公告內容管理','bell')}</div><h3 class="section-title">共用資料</h3><p class="small muted">AD／人員／帳號為平行共用模組（一期相依），GPS／裝置執行屬後續。學習派課只引用人員資料。</p><div class="adm-list">${nav('shared','前往外層 portal 共用模組','settings')}${nav('audit','學習操作紀錄','file')}</div>`+hint('本原型操作保存在此瀏覽器。正式資料權限須由後端同步驗證。');}
  function assignDraft(){const s=state();if(!s.admin.assignDraft)s.admin.assignDraft={type:s.admin.assignType||'course',contentId:'cash',due:'2026-10-30',branch:'all',department:'all',tag:'all',selected:[],note:'',notify:true};return s.admin.assignDraft;}
  function captureAssign(){const d=assignDraft();if(document.getElementById('adm-content')){d.contentId=val('adm-content');d.due=val('adm-due');d.note=val('adm-note');d.notify=checked('adm-notify');d.reinforcement=d.type==='course'&&checked('adm-reinforcement');d.selected=values('adm-person');for(const k of ['branch','department','major','tag','search','joinFrom','joinTo'])if(document.getElementById('assign-'+k))d[k]=val('assign-'+k);}return d;}
  function assignContent(d){return d.type==='course'?scopeCourses().filter(c=>c.status==='已上架'):state().noticeCatalog.filter(n=>(!n.status||['已發布','已上架','published'].includes(n.status))&&(!n.businessLine||readonly()||n.businessLine===myLine())&&(role()!=='branch'||!n.branches?.length||n.branches.includes(myBranch())));}
  function assign(){const d=assignDraft(),content=assignContent(d);if(!content.some(c=>c.id===d.contentId))d.contentId=content[0]?.id||'';const ppl=scopedFilter(scopePeople(true),d);return header('派發學習任務','選擇已上架內容，再依分公司、部別與標籤指定對象。')+`<div class="adm-segment">${[['course','課程'],['notice','公告']].map(([v,t])=>button(t,'adm-type',d.type===v?'selected':'',`data-type="${v}"`)).join('')}</div><div class="card stack"><label class="field">${d.type==='course'?'已上架課程':'已發布公告'}<select id="adm-content">${content.map(c=>`<option value="${esc(c.id)}" ${d.contentId===c.id?'selected':''}>${esc(c.title)} · ${esc(versionLabel(c.version))}</option>`).join('')}</select></label><label class="field">完成期限<input type="date" id="adm-due" value="${esc(d.due)}" min="${TODAY}"></label>${filterFields('assign',d)}<label class="field">搜尋人員<input id="assign-search" value="${esc(d.search||'')}" placeholder="姓名、員編、帳號或部號"></label><div class="adm-filter-grid"><label class="field">到職起日<input type="date" id="assign-joinFrom" value="${esc(d.joinFrom||'')}"></label><label class="field">到職迄日<input type="date" id="assign-joinTo" value="${esc(d.joinTo||'')}"></label></div>${button('套用人員篩選','adm-assign-filter','secondary adm-full')}<div class="row between"><strong>派發對象（${ppl.length}）</strong>${button('全選／取消','adm-select-all','adm-link')}</div>${ppl.length?ppl.map(p=>`<label class="adm-check"><input type="checkbox" name="adm-person" value="${esc(p.id)}" ${d.selected.includes(p.id)?'checked':''}><span><strong>${esc(p.name)}</strong><small>${esc(p.branch)} · ${esc(p.department)}</small><span class="adm-tags">${allTags(p).map(t=>badge(t)).join('')}</span><small>總時數 ${TrainingTime.format(TrainingTime.totalSeconds(state(),p.id))}</small><small>到職 ${esc(p.joinDate||'未提供')} · ${esc(majorFor(p))}</small></span>${badge(p.role)}</label>`).join(''):empty('此條件沒有啟用人員')}${d.type==='course'?`<label class="adm-check"><input type="checkbox" id="adm-reinforcement" ${d.reinforcement?'checked':''}><span>人工補強重派<small>即使曾得 100 分仍可指派；已有未完成任務則略過。必填補強原因。</small></span></label>`:''}<label class="field">派發說明／補強原因<textarea id="adm-note" rows="2" placeholder="填寫任務目的或補強原因">${esc(d.note)}</textarea></label><label class="adm-check"><input id="adm-notify" type="checkbox" ${d.notify?'checked':''}><span>記錄派課通知與 Email 待寄<small>僅保存示例狀態，不發送真實 Email 或推播。</small></span></label></div>${button('預覽派發名單 '+icon('arrow'),'adm-preview','primary adm-full',readonly()?'disabled':'')}`+emailPreview()+hint('一般派發按人員與內容版本去重；人工補強建立新輪次並要求新作答，保留原完課時數及歷次紀錄。');}
  function makePreview(type,content,ids,due,opts={}){const allowed=new Set(scopePeople(true).map(p=>p.id)),valid=[],skipped=[];for(const id of [...new Set(ids)])if(allowed.has(id))(canAssign(type,content,id,opts.reinforcement)?valid:skipped).push(id);pending={kind:'assign',type,content,ids:valid,skipped,due,...opts};D().modal(`<div class="adm-sheet"><span class="adm-kicker">${opts.reinforcement?'人工補強輪次':'派發預覽'}</span><h2>${esc(content.title)}</h2><p class="muted">${esc(versionLabel(content.version))} · 截止 ${esc(due)}</p>${opts.reinforcement?hint('補強原因：'+esc(opts.reason)+'；需完成新次測驗，舊成績與核定時數保留。'):''}<div class="adm-stats"><div><strong>${valid.length}</strong><span>將派發</span></div><div><strong>${skipped.length}</strong><span>重複／進行中略過</span></div></div>${valid.map(id=>`<div class="adm-simple-row">${icon('check')}<span>${esc(person(id).name)}<small>${esc(person(id).team)}</small></span></div>`).join('')}${skipped.length?hint('略過：'+skipped.map(id=>esc(person(id).name)).join('、')):''}${button('確認建立 '+valid.length+' 筆任務','adm-confirm','primary adm-full',valid.length?'':'disabled')}</div>`);}
  function buildAssignment(type,content,id,due,opts={}){const p=person(id),attempts=type==='course'?allAttempts(id,content.id,content.version):[],reinforcement=type==='course'&&!!opts.reinforcement;return{id:uid('assignment'),type,courseId:type==='course'?content.id:undefined,noticeId:type==='notice'?content.id:undefined,version:content.version??1,title:content.title,person:id,due,status:type==='course'?'未開始':'未讀',source:opts.source||'manual',ruleId:opts.ruleId||'',reason:opts.reason||'',note:opts.note||content.body||'',notificationSimulated:!!opts.notify,emailStatus:opts.notify?(p.email?'待寄':'缺 Email'):'未要求',createdAt:time(),assignedDate:simulationDate(),createdAtISO:new Date().toISOString(),reinforcement,cycleId:uid('cycle'),...(reinforcement?{requiredAttemptAfter:new Date().toISOString(),priorAttemptIds:attempts.map(a=>a.id).filter(Boolean),requiredAttemptCount:attempts.length}:{}),readAt:'',signedAt:'',hours:type==='course'?content.hours:0,trainingSeconds:type==='course'?TrainingTime.courseSeconds(content):0,organizationSnapshot:{branch:p.branch,department:p.department,businessLine:p.businessLine,departmentNumber:p.departmentNumber||'',departmentMajor:majorFor(p),gender:p.gender||'不提供',title:p.title||'未提供',rank:p.rank||'未提供',employmentStatus:p.employmentStatus||'在職'}};}
  function trackingFilter(){const a=state().admin;return{branch:a.branchFilter,department:a.departmentFilter,major:a.majorFilter,tag:a.tagFilter,search:a.trackingSearch};}
  function filteredAssignments(){const s=state(),f=s.admin.filter,x=trackingFilter();return scopeAssignments().filter(a=>{const o=trainingOrg(a),p=person(a.person);return(!s.admin.excludeCounters||p.role!=='專櫃')&&(!x.branch||x.branch==='all'||o.branch===x.branch)&&(!x.department||x.department==='all'||o.department===x.department)&&(!x.major||x.major==='all'||o.departmentMajor===x.major)&&(!x.tag||x.tag==='all'||allTags(p).includes(x.tag))&&(!x.search||[p.name,p.account,p.employeeNo].join(' ').toLowerCase().includes(x.search.toLowerCase()))&&(!s.admin.trackingCourse||s.admin.trackingCourse==='all'||a.courseId===s.admin.trackingCourse)&&(f==='all'||f===a.type||f==='late'&&overdue(a)||f==='done'&&complete(a)||f==='unread'&&a.status==='未讀'||f==='read'&&a.status==='已讀未確認'||f==='signed'&&a.status==='已確認')&&(s.admin.trackingSource==='all'||a.source===s.admin.trackingSource)&&(!s.admin.trackingFrom||a.due>=s.admin.trackingFrom)&&(!s.admin.trackingTo||a.due<=s.admin.trackingTo);});}
  function assignmentRow(a){const p=person(a.person);return `<button class="adm-record" data-action="adm-record" data-id="${esc(a.id)}"><span class="adm-row-icon">${icon(a.type==='course'?'book':'bell')}</span><span class="adm-grow"><strong>${esc(a.title)} <small>${esc(versionLabel(a.version))}</small></strong><small>${esc(p.name)} · 受訓時 ${esc(trainingOrg(a).branch)} · 截止 ${esc(a.due)}</small><span class="adm-tags">${badge(a.status,complete(a)?'good':'')}${overdue(a)?badge('逾期','warn'):''}${badge(({manual:'人工',manual_reinforcement:'人工補強',auto_rule:'新人規則',recurring:'常態派課',weakness:'弱項補強',score_threshold:'分數門檻'})[a.source]||a.source)}${a.reinforcement?badge('新作答輪次'):''}</span></span>${icon('arrow')}</button>`;}
  function tracking(){const s=state(),shown=filteredAssignments();return header('派發追蹤','清楚區分已讀、本人確認與課程完成。')+`<div class="card stack">${filterFields('tracking',trackingFilter())}<label class="field">指定課程<select id="tracking-course"><option value="all">全部課程與公告</option>${[...new Set(scopeAssignments().filter(a=>a.courseId).map(a=>a.courseId))].map(id=>`<option value="${esc(id)}" ${s.admin.trackingCourse===id?'selected':''}>${esc(s.catalog.find(c=>c.id===id)?.title||id)} · ${esc(id)}</option>`).join('')}</select></label><label class="adm-check"><input type="checkbox" id="tracking-exclude-counters" ${s.admin.excludeCounters?'checked':''}><span>排除專櫃（本次篩選）<small>預設包含；正式預設待確認</small></span></label><label class="field">人員搜尋<input id="tracking-search" value="${esc(s.admin.trackingSearch)}" placeholder="姓名、員編或帳號"></label><div class="adm-filter-grid"><label class="field">派發來源<select id="tracking-source">${[['all','全部來源'],['manual','人工派發'],['manual_reinforcement','人工補強'],['recurring','常態派課'],['auto_rule','新人規則'],['weakness','弱項補強'],['score_threshold','分數門檻']].map(([v,t])=>`<option value="${v}" ${s.admin.trackingSource===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">期限起日<input id="tracking-from" type="date" value="${esc(s.admin.trackingFrom)}"></label><label class="field">期限迄日<input id="tracking-to" type="date" value="${esc(s.admin.trackingTo)}"></label></div></div><div class="adm-chips">${[['all','全部'],['course','課程'],['notice','公告'],['late','逾期'],['unread','未讀'],['read','待確認'],['signed','已確認'],['done','完成']].map(([v,t])=>button(t,'adm-filter',s.admin.filter===v?'selected':'',`data-filter="${v}"`)).join('')}</div><div class="row between"><span class="small muted">${shown.length} 筆 · ${shown.filter(complete).length} 筆完成／簽收</span>${button('匯出目前結果','adm-export','adm-link')}</div><div class="adm-list">${shown.length?shown.map(assignmentRow).join(''):empty('沒有符合條件的派發紀錄')}</div>${button('模擬提醒目前篩選的未完成人員','adm-remind-all','secondary adm-full',readonly()?'disabled':'')}`+TrainingTime.batchDemo()+hint('匯出與提醒僅涵蓋目前篩選結果。分公司、部門及大類依示範快照篩選；正式取值事件待定。課程分類暫採最新更正，歷史口徑待確認。');}
  function assignmentDetail(id){const a=scopeAssignments().find(a=>a.id===id);if(!a)return D().toast('不在目前可閱範圍');const p=person(a.person),snapshot=a.organizationSnapshot||{};D().modal(`<div class="adm-sheet"><span class="adm-kicker">派發紀錄</span><h2>${esc(a.title)}</h2><p>${esc(p.name)} · ${badge(a.status,complete(a)?'good':'')}</p><div class="adm-timeline">${[['派發',a.createdAt],['閱讀',a.readAt||'尚未閱讀'],['本人確認',a.signedAt||'尚未確認'],['完成',a.completedAt||'尚未完成'],['模擬提醒',a.remindedAt||'尚未提醒']].map(([t,v])=>`<div><strong>${t}</strong><small>${esc(v)}</small></div>`).join('')}</div><div class="card"><strong>受訓時組織</strong><p class="small">${esc(snapshot.branch)} · ${esc(snapshot.department)} · ${esc(snapshot.businessLine)}</p><p class="small muted">目前組織：${esc(p.team)}</p></div>${learningDetail(a)}<p class="small">Email：${esc(a.emailStatus||'未要求（舊示例）')}（本機示例，未寄出）</p><p class="small">${esc(a.reason||a.note||'人工指定任務')}</p>${button('模擬提醒此人員','adm-remind','primary adm-full',`data-id="${esc(id)}" ${complete(a)||readonly()?'disabled':''}`)}</div>`);}
  function csvDownload(name,rows){const csv='\ufeff'+rows.map(r=>r.map(v=>{let t=String(v??'');if(/^[=+@\-\t\r]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
  function trackingRows(){const rows=[['任務ID','輪次ID','類型','內容ID','標題','版本','最新課程分類','姓名','員編','性別','職稱','職級','在職狀態','受訓時分公司','受訓時部門','受訓時部號','受訓時部別大類','業務線','目前分公司','目前部門','來源','補強原因','狀態','期限','課程時數 HH:mm:ss','本輪新增受訓時數 HH:mm:ss','教材完成','教材總數','測驗完成','測驗次數','問卷完成','最近學習時間','閱讀時間','確認時間','完成時間','課程秒數','本輪認列秒數','時數口徑','個人總時數 HH:mm:ss']];filteredAssignments().forEach(a=>{const p=person(a.person),o=trainingOrg(a),c=state().catalog.find(c=>c.id===a.courseId),m=a.type==='course'?metrics(a):{};rows.push([a.id,a.cycleId||'',a.type,a.courseId||a.noticeId,a.title,a.version,currentCategories(a.courseId).map(id=>CategoryTree.path(id)).join('、'),p.name,p.employeeNo,o.gender,o.title,o.rank,o.employmentStatus,o.branch,o.department,o.departmentNumber,o.departmentMajor,o.businessLine,p.branch,p.department,a.source,a.reason,a.status,a.due,a.type==='course'?TrainingTime.format(a.trainingSeconds??TrainingTime.courseSeconds(c)):'',a.type==='course'?(TrainingTime.assignmentSeconds(state(),a)===null?'待確認':a.status==='已完成'?TrainingTime.format(TrainingTime.assignmentSeconds(state(),a)):'未認列'):'',m.materialCountsKnown===false?'舊版未提供':m.materialCompleted??'',m.materialCountsKnown===false?'舊版未提供':m.materialTotal??'',m.quizCompleted??'',m.attemptCount??'',m.surveyCompleted??'',m.lastLearningAt||m.recentAt||'',a.readAt,a.signedAt,a.completedAt,a.type==='course'?(a.trainingSeconds??TrainingTime.courseSeconds(c)):'',a.type==='course'&&TrainingTime.assignmentSeconds(state(),a)!==null?TrainingTime.assignmentSeconds(state(),a):'',a.reinforcement?'重訓／重考是否另計待確認':'示例：完成時認列；正式認列事件待定',TrainingTime.format(TrainingTime.totalSeconds(state(),a.person))]);});return rows;}
  function exportConfig(){const a=state().admin,n=trackingRows()[0].length;if(!a.exportOrder||a.exportOrder.length!==n){a.exportOrder=Array.from({length:n},(_,i)=>i);a.exportSelected=[0,1,4,7,13,14,22,24,25,35,36,37];}return a;}
  function captureExport(){const a=exportConfig();a.exportSelected=values('export-column').map(Number);D().save();}
  function exportSheet(){const rows=trackingRows(),a=exportConfig();D().modal(`<div class="adm-sheet"><h2>選欄與匯出順序</h2><p class="small">全部篩選結果 ${rows.length-1} 筆 · ${a.excludeCounters?'已排除專櫃':'包含專櫃'}；依目前人員、組織、課程、來源、狀態與期限條件匯出。勾選欄位，以上移／下移調整順序。</p><div class="export-columns">${a.exportOrder.map((n,i)=>`<div class="export-column"><label><input type="checkbox" name="export-column" value="${n}" ${a.exportSelected.includes(n)?'checked':''}>${esc(rows[0][n])}</label><button class="secondary" data-action="adm-export-move" data-index="${i}" data-dir="-1" aria-label="上移 ${esc(rows[0][n])}" ${i===0?'disabled':''}>↑</button><button class="secondary" data-action="adm-export-move" data-index="${i}" data-dir="1" aria-label="下移 ${esc(rows[0][n])}" ${i===a.exportOrder.length-1?'disabled':''}>↓</button></div>`).join('')}</div><p class="small muted">一任務／輪次一列；重訓／重考是否另計待確認，未定秒數留空。</p>${button('下載選定欄位 CSV','adm-export-download','primary adm-full')}</div>`);}
  function exportTracking(){captureExport();const a=exportConfig(),cols=a.exportOrder.filter(n=>a.exportSelected.includes(n));if(!cols.length)return D().toast('請至少選一個欄位');const rows=trackingRows().map(row=>cols.map(n=>row[n]));csvDownload('遠百_派發追蹤_篩選結果.csv',rows);D().toast(`已匯出 ${rows.length-1} 筆、${cols.length} 欄全部篩選結果`);}


  function learningDetail(a){if(a.type!=='course')return '';const m=metrics(a);return `<div class="card"><strong>學習明細 · ${esc(versionLabel(a.version))}</strong><p class="small">${m.materialCountsKnown===false?'教材：舊版資料未提供':'教材 '+(m.materialCompleted??0)+' / '+(m.materialTotal??0)} · 測驗 ${m.quizCompleted??0} / ${m.quizTotal??1}<br>章節：${m.chapterConfigured?(m.chapterCompleted+' / '+m.chapterTotal):'未分章'} · 問卷 ${m.surveyCompleted??0} / ${m.surveyTotal??1} · 作答 ${m.attemptCount??0} 次<br>最近學習：${esc(m.lastLearningAt||m.recentAt||'尚未學習')}<br>最新分類：${currentCategories(a.courseId).map(t=>esc(CategoryTree.path(t))).join('、')}</p>${a.reinforcement?'<p class="small">此輪要求新的測驗通過；重訓／重考是否另計待確認，未定值留空。</p>':''}</div>`;}
  function categoryCreateFields(prefix){return `<label class="field">新增分類名稱<input id="${prefix}-new-category" placeholder="選填，儲存時一併建立並選取"></label><details><summary>新增分類的上層（可搜尋任一層）</summary>${CategoryTree.parentSelector(prefix+'-parent')}</details>`;}
  function categoryManagement(){return `<details class="card"><summary>分類樹管理</summary>${CategoryTree.initialize(state()).map(n=>`<div class="adm-simple-row"><span>${esc(CategoryTree.path(n.id))}</span>${button('⋯','adm-tree-menu','secondary',`data-id="${esc(n.id)}" aria-label="操作 ${esc(n.name)}"`)}</div>`).join('')}</details>`;}
  function categoryMenu(id){const n=state().categoryCatalog.find(n=>n.id===id);if(!n)return;D().modal(`<div class="adm-sheet"><h2>分類操作</h2><p>${esc(CategoryTree.path(id))}</p><label class="field">分類名稱<input id="tree-name" value="${esc(n.name)}"></label>${button('儲存改名','adm-tree-rename','primary adm-full',`data-id="${esc(id)}"`)}<label class="field">新增子分類名稱<input id="tree-child-name"></label>${button('新增子分類','adm-tree-child','secondary adm-full',`data-id="${esc(id)}"`)}</div>`);}
  function categoryEditor(id){const c=scopeCourses().find(c=>c.id===id);if(!c||role()!=='business')return D().toast('分類更正由所屬業管單位維護');D().modal(`<div class="adm-sheet"><h2>更正課程分類</h2><p class="small">${esc(c.title)}。只修正分類，沿用教材版本與歷史時數，報表按最新分類呈現。</p><div class="adm-option-grid">${CategoryTree.selector('fix-category',currentCategories(c.id))}</div>${categoryCreateFields('fix')}${button('儲存分類更正','adm-category-save','primary adm-full',`data-id="${esc(c.id)}"`)}</div>`);}

  function catalog(reviewOnly=false){const s=state(),list=scopeCourses().filter(c=>(!reviewOnly||['待審核','已核准','已退回','已下架','已上架'].includes(c.status))&&(s.admin.catalogFilter==='all'||c.status===s.admin.catalogFilter));return header(reviewOnly?'課程審核與上架':'課程分類與版本',reviewOnly?'授權業管可直接上架；分店可向上送審，核准後上架。送審路徑作者不能自審。':'多選分類、核定時數與版本，連動學員課程及派課選單。')+`<div class="adm-chips">${['all','草稿','待審核','已核准','已上架','已退回','已下架'].map(v=>button(v==='all'?'全部':v,'adm-catalog-filter',s.admin.catalogFilter===v?'selected':'',`data-filter="${v}"`)).join('')}</div>${!reviewOnly&&!readonly()?categoryManagement():''}${!reviewOnly&&!readonly()?button('新增課程草稿','adm-course-new','primary adm-full'):''}<div class="adm-list">${list.length?list.map(c=>`<button class="adm-record" data-action="adm-course-detail" data-id="${esc(c.id)}"><span class="adm-row-icon">${icon('book')}</span><span class="adm-grow"><strong>${esc(c.title)}</strong><small>v${c.version} · ${TrainingTime.format(c.trainingSeconds)} · ${esc(c.ownerBranch)}</small><span class="adm-tags">${badge(c.status,c.status==='已上架'?'good':'')}${c.categories.map(t=>badge(CategoryTree.path(t))).join('')}</span></span>${icon('arrow')}</button>`).join(''):empty('沒有符合狀態的課程')}</div>`+hint('本案採課程時數，實看時數未納。正式認列事件待確認。');}
  function editableCourse(c){return !readonly()&&!sys()&&courseAllowed(c)&&['草稿','已退回'].includes(c.status)&&(role()==='business'||(role()==='branch'&&c.ownerBranch===myBranch()));}
  function courseDetail(id){const c=scopeCourses().find(c=>c.id===id);if(!c)return D().toast('不在目前可閱範圍');selectedCourse=c.id;const edit=editableCourse(c);D().modal(`<div class="adm-sheet"><span class="adm-kicker">課程版本 ${esc(c.id)}</span><h2>${esc(c.title)}</h2><div class="adm-tags">${badge(c.status)}${badge('v'+c.version)}${badge(TrainingTime.format(c.trainingSeconds))}</div><p class="small muted">建立單位：${esc(c.ownerBranch)} · ${esc(c.businessLine)}<br>作者：${esc(c.authorId)}${c.reviewerId?'<br>審核者：'+esc(c.reviewerId):''}</p><p>${esc(c.description)}</p><div class="adm-tags">${c.categories.map(t=>badge(CategoryTree.path(t))).join('')}</div><div class="adm-simple-row"><span>課程 AI 助手</span><strong>${c.assistantEnabled?'開啟':'關閉'}</strong></div>${courseMetadata(c)}${courseRuleSummary(c)}<div class="adm-simple-row"><span>教材與題庫</span><strong>${courseContent(c).units.length} 份教材 · ${courseContent(c).questions.length} 題</strong></div>${c.reviewNote?`<div class="adm-hint">審核意見：${esc(c.reviewNote)}</div>`:''}<div class="adm-action-stack">${role()==='business'?button('更正分類（沿用版本）','adm-category-edit','secondary',`data-id="${esc(c.id)}"`):''}${button('檢視教材與題庫','adm-course-content-preview','secondary',`data-id="${esc(c.id)}"`)}${edit?button('編輯教材與題庫','adm-course-content-edit','secondary',`data-id="${esc(c.id)}"`):''}${edit?button('編輯基本資料與分類','adm-course-edit','secondary',`data-id="${esc(c.id)}"`):''}${canDirectPublish(c)?button('直接上架（授權業管）','adm-course-direct-publish','primary',`data-id="${esc(c.id)}"`):''}${['草稿','已退回'].includes(c.status)&&edit?button('送交業管審核','adm-course-submit','primary',`data-id="${esc(c.id)}"`):''}${c.status==='待審核'&&canReview()?`<label class="field">審核意見<textarea id="course-review-note" rows="2" placeholder="退回時必填；核准可留摘要"></textarea></label><div class="adm-button-pair">${button('退回修改','adm-course-reject','secondary',`data-id="${esc(c.id)}" ${(c.authorId===actor()||c.updatedBy===actor())?'disabled':''}`)}${button('核准此版本','adm-course-approve','primary',`data-id="${esc(c.id)}" ${(c.authorId===actor()||c.updatedBy===actor())?'disabled':''}`)}</div>${(c.authorId===actor()||c.updatedBy===actor())?hint('此版本由你建立或修改，必須由另一位獲授權的業管審核。'):''}`:''}${['已核准','已下架'].includes(c.status)&&canPublish(c)?button('上架此版本','adm-course-publish','primary',`data-id="${esc(c.id)}"`):''}${c.status==='已上架'&&canPublish(c)?button('下架此版本','adm-course-unpublish','secondary',`data-id="${esc(c.id)}"`):''}${['已上架','已核准','已下架'].includes(c.status)&&!readonly()?button('建立下一版草稿','adm-course-version','secondary',`data-id="${esc(c.id)}"`):''}</div><p class="tiny muted">下架不刪除歷史派發與完成紀錄；新派課只可選已上架內容。</p></div>`);}
  function courseEditor(id){let c=id?scopeCourses().find(c=>c.id===id):null;if(c&&!editableCourse(c))return D().toast('只有草稿或退回版本可編輯');const s=state();if(!c)c={id:'',title:'',categories:[],hours:0.5,description:'',assistantEnabled:false,ownerBranch:role()==='branch'?myBranch():'總公司',businessLine:myLine(),version:1};selectedCourse=c.id;D().modal(`<div class="adm-sheet"><h2>${c.id?'編輯課程草稿':'新增課程草稿'}</h2><div class="stack"><label class="field">課程名稱<input id="course-title" value="${esc(c.title)}" maxlength="100"></label><label class="field">課程說明<textarea id="course-description" rows="3">${esc(c.description)}</textarea></label><label class="field">課程時數（整秒）<input id="course-seconds" type="number" min="1" max="360000" step="1" value="${TrainingTime.courseSeconds(c)}"></label><div><strong class="small">課程分類（可多選）</strong><div class="adm-option-grid">${CategoryTree.selector('course-category',c.categories)}</div></div>${categoryCreateFields('course')}${courseMetadataFields(c)}${courseRuleFields(c)}<label class="adm-check"><input type="checkbox" id="course-ai" ${c.assistantEnabled?'checked':''}><span>開啟這門課的 AI 助手<small>不影響 APP 一般 AI 聊天室。財務專櫃課程可個別關閉。</small></span></label>${button('儲存並編輯教材','adm-course-save','primary')}</div></div>`);}

  const QUESTION_TYPES={single:'單選題',truefalse:'是非題',multiple:'多選題',short:'簡答題'};
  function courseContent(c){const full=window.LearningUI?.getCourse(c.id)||c;return {units:Array.isArray(full.units)?full.units:[],questions:Array.isArray(full.questions)?full.questions:[]};}
  function dispatchRule(c){const r=c.dispatchRule;if(!r)return null;if(!Array.isArray(r.bands)){r.bands=[{min:Number(r.scoreMin??0),max:Number(r.scoreMax??59),days:Number(r.intervalDays??7),action:r.nextCourseId?'next':'within',nextCourseId:r.nextCourseId||''}];delete r.executionStatus;}return r;}
  function defaultDispatchRule(){return{cycleDays:30,anchorDate:simulationDate(),bands:[{min:0,max:59,days:3,action:'within',nextCourseId:''},{min:60,max:80,days:7,action:'after',nextCourseId:''}]};}
  function scoreBandFields(b,i,c){return `<div class="card stack" data-score-band><strong>分數級距 ${i+1}</strong><div class="adm-filter-grid"><label class="field">分數下限（含）<input data-band="min" type="number" min="0" max="100" step="1" value="${b.min}"></label><label class="field">分數上限（含）<input data-band="max" type="number" min="0" max="100" step="1" value="${b.max}"></label><label class="field">天數<input data-band="days" type="number" min="1" max="365" step="1" value="${b.days}"></label><label class="field">動作<select data-band="action">${[['within','N 天內重派同課'],['after','N 天後重派同課'],['next','指定下一門課（N 天內完成）']].map(([v,t])=>`<option value="${v}" ${b.action===v?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="field">指定下一門課<select data-band="nextCourseId"><option value="">請選擇</option>${scopeCourses().filter(x=>x.id!==c.id&&x.status==='已上架').map(x=>`<option value="${esc(x.id)}" ${b.nextCourseId===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label>${button('刪除此段','adm-band-remove','secondary')}</div>`;}
  function courseRuleFields(c){const r=dispatchRule(c)||defaultDispatchRule();return `<fieldset class="card stack"><legend>課程派課規則</legend><p class="small muted">測驗送出後依總分級距建立任務；週期課在示範日期推進時執行。級距含上下限且不可重疊。</p><label class="field">課程週期（日）<input id="course-cycle-days" type="number" min="0" max="365" step="1" value="${r.cycleDays}"><small>0 為不定期</small></label><div id="score-bands">${r.bands.map((b,i)=>scoreBandFields(b,i,c)).join('')}</div>${button('新增分數級距','adm-band-add','secondary')}</fieldset>`;}
  function bandDescription(b){return `${b.min}–${b.max} 分（含）：${b.action==='next'?esc(D().state.catalog.find(c=>c.id===b.nextCourseId)?.title||'未指定課程')+'，'+b.days+' 天內完成':b.days+(b.action==='after'?' 天後重派同課':' 天內重派同課')}`;}
  function courseRuleSummary(c){const r=dispatchRule(c);return `<div class="card"><strong>課程派課規則</strong><p class="small">${r?`週期：${r.cycleDays?r.cycleDays+' 日':'不定期'}<br>${r.bands.map(bandDescription).join('<br>')}`:'尚未設定'}</p></div>`;}
  function readDispatchRule(){return {cycleDays:Number(val('course-cycle-days')),anchorDate:dispatchRule(D().state.catalog.find(c=>c.id===selectedCourse)||{})?.anchorDate||simulationDate(),bands:Array.from(document.querySelectorAll('[data-score-band]')).map(row=>Object.fromEntries(['min','max','days','action','nextCourseId'].map(k=>{const v=row.querySelector(`[data-band="${k}"]`).value;return[k,['min','max','days'].includes(k)?v===''?NaN:Number(v):v];}))) };}
  function validDispatchRule(r){if(val('course-cycle-days')===''||!Number.isInteger(r.cycleDays)||r.cycleDays<0||r.cycleDays>365)return false;return r.bands.every((b,i)=>[b.min,b.max,b.days].every(Number.isInteger)&&b.min>=0&&b.max<=100&&b.min<=b.max&&b.days>=1&&b.days<=365&&['within','after','next'].includes(b.action)&&(b.action!=='next'||scopeCourses().some(c=>c.id===b.nextCourseId&&c.id!==selectedCourse&&c.status==='已上架'))&&!r.bands.some((other,j)=>j<i&&b.min<=other.max&&b.max>=other.min));}
  function createDispatchTask(c,pid,key,date,days,source,reason,after=false){const s=D().state;if(s.assignments.some(a=>a.ruleKey===key))return false;const a=buildAssignment('course',c,pid,datePlus(days,date),{source,reason,notify:true,reinforcement:true});Object.assign(a,{ruleKey:key,assignedDate:date,availableFrom:after?datePlus(days,date):date,cycleId:key});s.assignments.unshift(a);return true;}
  function dispatchScore(c,attempt){const r=dispatchRule(c),s=D().state;if(!r||!attempt?.id)return 0;const b=r.bands.find(b=>attempt.score>=b.min&&attempt.score<=b.max);if(!b)return 0;const target=s.catalog.find(x=>x.id===(b.action==='next'?b.nextCourseId:c.id)&&x.status==='已上架'&&x.businessLine===c.businessLine);if(!target)return 0;const date=simulationDate(c.businessLine),key=['score',attempt.userId,target.id,target.version,attempt.id].join(':');return Number(createDispatchTask(target,attempt.userId,key,date,b.days,'score_threshold','分數門檻：'+bandDescription(b),b.action==='after'));}
  function executePeriodic(){const s=D().state;let count=0;for(const c of s.catalog){const r=dispatchRule(c);if(c.status!=='已上架'||!(r?.cycleDays>0))continue;const date=simulationDate(c.businessLine),pids=[...new Set(s.assignments.filter(a=>a.type==='course'&&a.courseId===c.id&&versionKey(a.version)===versionKey(c.version)&&(!a.availableFrom||a.availableFrom<=date)).map(a=>a.person))];for(const pid of pids){const p=s.people.find(p=>p.id===pid);if(!p||p.status!=='啟用'||p.businessLine!==c.businessLine)continue;const originals=s.assignments.filter(a=>a.type==='course'&&a.courseId===c.id&&a.person===pid&&a.source!=='recurring'&&versionKey(a.version)===versionKey(c.version));const first=originals.map(a=>a.assignedDate||dateOf(a.createdAt)).filter(Boolean).sort()[0]||r.anchorDate||TODAY;for(let round=datePlus(r.cycleDays,first);round<=date;round=datePlus(r.cycleDays,round)){const key=['periodic',pid,c.id,c.version,round].join(':');count+=Number(createDispatchTask(c,pid,key,round,r.cycleDays,'recurring','週期性派課：每 '+r.cycleDays+' 日'));}}}return count;}
  function courseMetadata(c){return `<div class="card"><strong>課程資訊</strong><p class="small">講師：${esc(c.instructor||'財務訓練小組（示例）')} · ${esc(c.difficulty||'初階')}<br>開放方式：${c.visibility==='private'?'指定派課對象':'業務線內公開'}<br>上架期間：${esc(c.publishStart||'不限制')} ～ ${esc(c.publishEnd||'不限制')}<br>及格分數：${Number(c.passScore??60)} 分 · 作答時間：${Number(c.timeLimit)||'不限制'}${Number(c.timeLimit)?' 分鐘':''}</p>${c.objectives?`<p class="small">學習目標：${esc(c.objectives)}</p>`:''}${c.prerequisites?`<p class="small">先備條件：${esc(c.prerequisites)}</p>`:''}</div>`;}
  function courseMetadataFields(c){return `<label class="field">學習目標<textarea id="course-objectives" rows="2" placeholder="學員完成課程後可以做到什麼">${esc(c.objectives||'')}</textarea></label><label class="field">先備條件<input id="course-prerequisites" value="${esc(c.prerequisites||'')}" placeholder="例如：完成新人報到；無則填無"></label><div class="adm-filter-grid"><label class="field">講師／負責單位<input id="course-instructor" value="${esc(c.instructor||'財務訓練小組（示例）')}"></label><label class="field">難易度<select id="course-difficulty">${options(['初階','中階','進階'],c.difficulty||'初階',null)}</select></label><label class="field">開放方式<select id="course-visibility"><option value="public" ${c.visibility!=='private'?'selected':''}>業務線內公開</option><option value="private" ${c.visibility==='private'?'selected':''}>指定派課對象</option></select></label><label class="field">及格分數<input id="course-pass-score" type="number" min="0" max="100" value="${Number(c.passScore??60)}"></label><label class="field">作答時間（分鐘）<input id="course-time-limit" type="number" min="0" max="180" value="${Number(c.timeLimit)||0}"><small>0 為不限制；本機參考計時</small></label><label class="field">上架起日<input id="course-publish-start" type="date" value="${esc(c.publishStart||'')}"></label><label class="field">上架迄日<input id="course-publish-end" type="date" value="${esc(c.publishEnd||'')}"></label></div>`;}
  function validateContent(c,data=courseContent(c)){if(data.units.length<2||data.questions.length<3)return '請先備妥至少 2 份教材與 3 道測驗題';for(let i=0;i<data.units.length;i++){const u=data.units[i];if(!u.title?.trim()||!(u.body?.trim()||u.sections?.some(x=>x.text?.trim())))return `教材 ${i+1} 請填寫標題與正文`;if(!Number.isFinite(Number(u.duration))||Number(u.duration)<=0)return `教材 ${i+1} 請填寫有效分鐘數`;}
    for(let i=0;i<data.questions.length;i++){const q=data.questions[i],type=q.type||'single',opts=q.options||[];if(!q.question?.trim()||!q.category?.trim())return `第 ${i+1} 題請填寫題目與分類`;if(!Number.isFinite(Number(q.weight??1))||Number(q.weight??1)<=0)return `第 ${i+1} 題配分必須大於 0`;if(type==='short'){if(!q.acceptedAnswers?.some(x=>String(x).trim()))return `第 ${i+1} 題請填寫可接受答案`;}else{if(opts.length<2||opts.some(x=>!String(x).trim())||new Set(opts.map(x=>String(x).trim())).size!==opts.length)return `第 ${i+1} 題選項不可空白或重複`;const answers=type==='multiple'?q.answer:[q.answer];if(!Array.isArray(answers)||!answers.length||answers.some(x=>!Number.isInteger(x)||x<0||x>=opts.length))return `第 ${i+1} 題請指定有效正確答案`;}}
    return '';}
  function materialPreview(id){const c=scopeCourses().find(c=>c.id===id);if(!c)return;const data=courseContent(c);D().modal(`<div class="adm-sheet"><span class="adm-kicker">教材與題庫預覽 · ${esc(versionLabel(c.version))}</span><h2>${esc(c.title)}</h2>${courseMetadata(c)}${data.units.map((u,i)=>`<details class="adm-content-panel" ${i===0?'open':''}><summary>教材 ${i+1}｜${esc(u.title)}</summary><p class="small muted">${esc(u.type||'講義')} · ${esc(u.duration)} 分鐘 · ${(u.categories?.length?u.categories:c.categories).map(id=>esc(CategoryTree.path(id))).join('、')}</p><p class="small"><a href="${esc(u.pdfUrl||'assets/cash-u1.pdf')}" target="_blank" rel="noopener">開啟自製示範 PDF</a>；下方為文字摘錄</p>${u.body?`<p class="adm-preserve small">${esc(u.body)}</p>`:''}${(u.sections||[]).map(x=>`<strong class="small">${esc(x.heading)}</strong><p class="small">${esc(x.text)}</p>`).join('')}${(u.keyPoints||[]).map(x=>`<p class="small">· ${esc(x)}</p>`).join('')}</details>`).join('')}${data.questions.map((q,i)=>{const type=q.type||'single',answers=type==='multiple'?q.answer:[q.answer];return `<details class="adm-content-panel"><summary>第 ${i+1} 題｜${esc(QUESTION_TYPES[type]||'單選題')} · ${esc(q.category)}</summary><p class="small">${esc(q.question)}</p>${type==='short'?`<p class="small">可接受答案：${(q.acceptedAnswers||[]).map(esc).join('、')}</p>`:(q.options||[]).map((o,n)=>`<p class="small">${String.fromCharCode(65+n)}. ${esc(o)} ${answers?.includes(n)?badge('正確答案','good'):''}</p>`).join('')}<p class="small muted">配分權重：${Number(q.weight)||1} · 來源：${esc(CategoryTree.sourceLabel({...c,units:data.units},q))}<br>${esc(q.explanation||'尚未填寫解析')}</p></details>`;}).join('')}${!data.units.length?empty('尚未建立教材與題庫'):''}${editableCourse(c)?button('編輯教材與題庫','adm-course-content-edit','primary adm-full',`data-id="${esc(c.id)}"`):''}${button('返回課程版本','adm-course-detail','secondary adm-full',`data-id="${esc(c.id)}"`)}</div>`);}
  function materialEditor(id){const c=scopeCourses().find(c=>c.id===id);if(!c||!editableCourse(c))return D().toast('只有授權範圍內的草稿或退回版本可編輯教材');const data=courseContent(c);contentDraft={id:c.id,role:role(),branch:myBranch(),line:myLine(),units:JSON.parse(JSON.stringify(data.units)),questions:JSON.parse(JSON.stringify(data.questions))};while(contentDraft.units.length<2)contentDraft.units.push({id:uid('unit'),title:'',body:'',type:contentDraft.units.length?'情境教材':'講義',duration:5});if(!contentDraft.questions.length)contentDraft.questions=Object.keys(QUESTION_TYPES).map(type=>({type,question:'',options:type==='truefalse'?['是','否']:['','',''],answer:type==='multiple'?[0]:0,acceptedAnswers:[],category:'',explanation:'',weight:1,unit:0}));while(contentDraft.questions.length<3)contentDraft.questions.push({type:'single',question:'',options:['','',''],answer:0,category:'',weight:1,unit:0});
    D().modal(`<div class="adm-sheet"><span class="adm-kicker">課程製作 · ${esc(versionLabel(c.version))}</span><h2>教材與題庫</h2><p class="small muted">${esc(c.title)}。此處編輯文字摘錄與測驗；學員逐件開啟自製 PDF 後確認。新建單元暫用結帳示範 PDF，不會將文字轉成原始文件。正式上傳與轉檔未接線。</p>${contentDraft.units.map((u,i)=>`<details class="adm-content-panel" ${i===0?'open':''}><summary>教材 ${i+1}｜${esc(u.title||'尚未命名')}</summary><div class="stack"><label class="field">單元標題<input id="cu-title-${i}" value="${esc(u.title||'')}" maxlength="100"></label><div class="adm-filter-grid"><label class="field">教材形式<select id="cu-type-${i}">${options(['講義','情境教材'],u.type||'講義',null)}</select></label><label class="field">預估分鐘<input type="number" id="cu-duration-${i}" min="1" max="240" value="${Number(u.duration)||5}"></label></div><div><strong>單元分類（可多選，未選時使用課程分類）</strong>${CategoryTree.selector('unit-category-'+i,u.categories||[])}</div><label class="field">教材正文<textarea rows="7" id="cu-body-${i}" placeholder="輸入完整教材；可使用分段與換行">${esc([u.body||'',...(u.sections||[]).map(x=>[x.heading,x.text].filter(Boolean).join('\n'))].filter(Boolean).join('\n\n'))}</textarea></label><label class="field">學習重點（每行一項）<textarea rows="3" id="cu-points-${i}">${esc((u.keyPoints||[]).join('\n'))}</textarea></label></div></details>`).join('')}<h3 class="section-title">測驗題庫</h3><p class="small muted">依配分加權計算總分。多選須完全符合；簡答以設定答案去空白、不分大小寫精確比對，非 AI 評分。</p>${contentDraft.questions.map((q,i)=>{const type=q.type||'single',opts=q.options?.length?q.options:['','',''],answer=Array.isArray(q.answer)?q.answer:[q.answer??0];return `<details class="adm-content-panel"><summary>第 ${i+1} 題｜${esc(QUESTION_TYPES[type]||'單選題')}</summary><div class="stack"><div class="adm-filter-grid"><label class="field">題型<select id="cq-type-${i}">${Object.entries(QUESTION_TYPES).map(([v,t])=>`<option value="${v}" ${type===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">配分權重<input type="number" id="cq-weight-${i}" min="1" max="100" value="${Number(q.weight)||1}"></label></div><label class="field">題目<textarea rows="3" id="cq-question-${i}">${esc(q.question||'')}</textarea></label><div id="cq-options-${i}" class="stack adm-question-answer">${opts.map((o,n)=>`<label class="field">選項 ${String.fromCharCode(65+n)}<input id="cq-option-${i}-${n}" value="${esc(o)}"></label>`).join('')}</div><label id="cq-single-${i}" class="field adm-question-answer">正確答案<select id="cq-answer-${i}">${opts.map((o,n)=>`<option value="${n}" ${answer[0]===n?'selected':''}>${String.fromCharCode(65+n)}</option>`).join('')}</select></label><div id="cq-multiple-${i}" class="adm-question-answer"><strong class="small">正確答案（可複選）</strong><div class="adm-option-grid">${opts.map((o,n)=>`<label class="adm-choice"><input type="checkbox" name="cq-multi-${i}" value="${n}" ${answer.includes(n)?'checked':''}>${String.fromCharCode(65+n)}</label>`).join('')}</div></div><label id="cq-truefalse-${i}" class="field adm-question-answer">正確答案<select id="cq-tf-answer-${i}"><option value="0" ${Number(q.answer)!==1?'selected':''}>是</option><option value="1" ${Number(q.answer)===1?'selected':''}>否</option></select></label><label id="cq-short-${i}" class="field adm-question-answer">可接受答案（以「、」分隔）<textarea rows="2" id="cq-accepted-${i}">${esc((q.acceptedAnswers||[]).join('、'))}</textarea></label><div class="adm-filter-grid"><label class="field">題型／弱項分類<input id="cq-category-${i}" value="${esc(q.category||'')}" placeholder="例如：發票作業"></label><label class="field">來源課程／單元／分類<select id="cq-unit-${i}">${contentDraft.units.map((u,n)=>`<option value="${n}" ${Number(q.unit||0)===n?'selected':''}>${esc(c.title)} ／ ${esc(u.title||`單元 ${n+1}`)} ／ ${esc((u.categories?.length?u.categories:c.categories).map(id=>CategoryTree.path(id)).join("、"))}</option>`).join('')}</select></label></div><label class="field">答案解析<textarea rows="3" id="cq-explanation-${i}">${esc(q.explanation||'')}</textarea></label></div></details>`;}).join('')}<div class="adm-action-stack">${button('儲存教材與題庫','adm-course-content-save','primary',`data-id="${esc(c.id)}"`)}${button('取消並返回課程','adm-course-detail','secondary',`data-id="${esc(c.id)}"`)}</div></div>`);
    contentDraft.questions.forEach((q,i)=>{const change=()=>{const type=val('cq-type-'+i);for(const name of ['options','single','multiple','truefalse','short']){const node=document.getElementById(`cq-${name}-${i}`);if(node)node.hidden=name==='options'?!['single','multiple'].includes(type):name!==type;}};document.getElementById('cq-type-'+i)?.addEventListener('change',change);change();});}
  function saveMaterial(id){const draft=contentDraft,c=scopeCourses().find(c=>c.id===id);if(!draft||draft.id!==id||!c||!editableCourse(c)||draft.role!==role()||draft.branch!==myBranch()||draft.line!==myLine())return D().toast('課程或管理身分已變更，請重新開啟編輯器');const units=draft.units.map((u,i)=>({...u,id:u.id||uid('unit'),title:val('cu-title-'+i).trim(),type:val('cu-type-'+i),duration:Number(val('cu-duration-'+i)),body:val('cu-body-'+i).trim(),categories:values('unit-category-'+i),sections:[],keyPoints:val('cu-points-'+i).split('\n').map(x=>x.trim()).filter(Boolean)}));const questions=draft.questions.map((q,i)=>{const type=val('cq-type-'+i),opts=type==='truefalse'?['是','否']:type==='short'?[]:(q.options?.length?q.options:['','','']).map((o,n)=>val(`cq-option-${i}-${n}`).trim());return{...q,type,question:val('cq-question-'+i).trim(),options:opts,answer:type==='multiple'?values('cq-multi-'+i).map(Number):type==='truefalse'?Number(val('cq-tf-answer-'+i)):type==='short'?null:Number(val('cq-answer-'+i)),acceptedAnswers:type==='short'?val('cq-accepted-'+i).split(/[、\n]/).map(x=>x.trim()).filter(Boolean):[],weight:Number(val('cq-weight-'+i)),category:val('cq-category-'+i).trim(),explanation:val('cq-explanation-'+i).trim(),unit:Number(val('cq-unit-'+i))};});questions.forEach(q=>{const src=CategoryTree.source({...c,units},{...q,source:null});q.source={courseId:src.courseId,unitId:src.unitId};});const candidate={...c,units,questions,contentConfigured:true};const error=validateContent(candidate,candidate);if(error)return D().toast(error);Object.assign(c,{units,questions,contentConfigured:true,duration:units.reduce((n,u)=>n+u.duration,0),updatedAt:time(),updatedBy:actor(),status:'草稿'});recordAudit('儲存教材與題庫',c.id,`${units.length} 份教材、${questions.length} 題測驗`);contentDraft=null;D().save();materialPreview(c.id);D().toast('教材與題庫已儲存，可預覽後送審');}

  function courseTransition(action,id){const c=scopeCourses().find(c=>c.id===id);if(!c)return;const expected={'adm-course-direct-publish':['草稿','已退回'],'adm-course-submit':['草稿','已退回'],'adm-course-reject':['待審核'],'adm-course-approve':['待審核'],'adm-course-publish':['已核准','已下架'],'adm-course-unpublish':['已上架']}[action];if(!expected?.includes(c.status))return D().toast('此狀態不能執行該操作');if(['adm-course-direct-publish','adm-course-submit','adm-course-publish'].includes(action)){const error=validateContent(c);if(error)return D().toast(error);}if(action==='adm-course-direct-publish'){if(!canDirectPublish(c))return D().toast('直接上架限授權業管單位');c.status='已上架';c.publishedAt=time();c.publicationRoute='direct';c.publishedBy=actor();}else if(action==='adm-course-submit'){if(!editableCourse(c))return D().toast('沒有送審權限');c.status='待審核';c.submittedAt=time();c.publicationRoute='review';}else{if(['adm-course-publish','adm-course-unpublish'].includes(action)?!canPublish(c):!canReview())return D().toast('核准由業管執行；分店只能上／下架本店已核准版本');if(['adm-course-reject','adm-course-approve'].includes(action)&&(c.authorId===actor()||c.updatedBy===actor()))return D().toast('作者或最後編輯者不能審核自己的版本');const note=val('course-review-note').trim();if(action==='adm-course-reject'&&!note)return D().toast('退回請填寫修改意見');c.status=({'adm-course-reject':'已退回','adm-course-approve':'已核准','adm-course-publish':'已上架','adm-course-unpublish':'已下架'})[action];if(['adm-course-reject','adm-course-approve'].includes(action)){c.reviewNote=note;c.reviewerId=actor();c.reviewedAt=time();}if(action==='adm-course-publish')c.publishedAt=time();}recordAudit(c.status,c.id,c.title);commit('課程版本已'+c.status.replace(/^已/,''));}

  const RULE_LABEL={newhire:'新人必修',recurring:'常態課程',weakness:'題型弱項補強'};
  const FREQUENCY_LABEL={daily:'每天一次',weekly:'每 7 天一次',monthly:'每曆月一次'};
  function ruleDescription(r){return r.type==='newhire'?`到職 ${policyFor(r.businessLine).months} 個曆月內，首次派發`:r.type==='recurring'?FREQUENCY_LABEL[r.frequency]:`觀察 ${r.days} 日 · ${r.category}錯誤率 ≥ ${r.threshold}% · ${FREQUENCY_LABEL[r.frequency]}`;}
  function rulePeriod(r){const date=simulationDate(r.businessLine);return r.type==='newhire'?'once':r.frequency==='monthly'?date.slice(0,7):r.frequency==='daily'?date:'week-'+Math.floor(new Date(date+'T12:00:00Z').getTime()/604800000);}
  function ruleTaskKey(r,p,c){return[r.id,r.version||1,p,c.id,versionKey(c.version),rulePeriod(r)].join(':');}
  function ruleTasks(r){const tasks=[],skips=[],ppl=rulePeople(r);for(const p of ppl)for(const cid of r.courseIds){const c=D().state.catalog.find(c=>c.id===cid&&c.status==='已上架'&&c.businessLine===r.businessLine);if(!c)continue;const old=matchingTasks('course',c,p.id),key=ruleTaskKey(r,p.id,c);let why='';if(old.some(a=>!taskComplete(a)))why='已有進行中任務';else if(old.some(a=>a.ruleKey===key))why='本週期已派發';else if(r.type==='newhire'&&old.length)why='新人必修已派過';else if(old.length){const last=old.map(a=>a.assignedDate||dateOf(a.createdAtISO||a.createdAt)).filter(Boolean).sort().at(-1);const next=last&&(r.frequency==='monthly'?addMonths(last,1):datePlus(r.frequency==='daily'?1:7,last));if(next&&simulationDate(r.businessLine)<next)why='重派間隔未到（'+next+'）';}const task={person:p.id,course:c,reason:why,reinforcement:old.length>0||progressRecords(p.id,c.id,c.version).some(x=>x.passed)};(why?skips:tasks).push(task);}return{ppl,tasks,skips};}

  function applyRuleTasks(r){const s=D().state,{tasks}=ruleTasks(r);let count=0;for(const t of tasks){const key=ruleTaskKey(r,t.person,t.course);if(s.assignments.some(a=>a.ruleKey===key))continue;const a=buildAssignment('course',t.course,t.person,datePlus(r.deadlineDays,simulationDate(r.businessLine)),{source:r.type==='weakness'?'weakness':r.type==='recurring'?'recurring':'auto_rule',ruleId:r.id,reason:r.name,notify:true,reinforcement:t.reinforcement});Object.assign(a,{ruleVersion:r.version||1,rulePeriod:rulePeriod(r),ruleKey:key,assignedDate:simulationDate(r.businessLine)});s.assignments.unshift(a);count++;}if(count){r.lastRun=time();r.lastCreated=count;s.audit.unshift({id:uid('audit'),at:time(),actor:'系統模擬',branch:r.ownerBranch,businessLine:r.businessLine,action:r.type==='newhire'?'新人自動派課':'規則補發',entity:r.id,detail:count+' 筆'});D().save();}return count;}
  function rules(){const rules=state().autoRules.filter(ruleAllowed);return header('派課規則與預覽','啟用的新人規則會於初始化、每次顯示與人員資料變更時自動派課；預覽與補發供補漏使用。')+policyPanel()+`${!readonly()?button('新增派課規則','adm-rule-new','primary adm-full'):''}<div class="adm-list">${rules.map(r=>`<button class="adm-record" data-action="adm-rule-detail" data-id="${esc(r.id)}"><span class="adm-row-icon">${icon(r.type==='newhire'?'users':'chart')}</span><span class="adm-grow"><strong>${esc(r.name)}</strong><small>${esc(ruleDescription(r))}<br>${r.deadlineDays} 日內完成</small><span class="adm-tags">${badge(r.enabled?'啟用':'停用',r.enabled?'good':'')}${badge(RULE_LABEL[r.type]||r.type)}</span></span>${icon('arrow')}</button>`).join('')}</div>`+hint('弱項直接彙整學員歷次作答的題型與答案，含歷版教材；不採人員示例弱項欄位或總分。新人規則自動執行；弱項規則保留預覽與手動補發。');}
  function ruleAllowed(r){return !sys()&&(readonly()||r.businessLine===myLine())&&(role()!=='branch'||r.branch==='all'||r.branch===myBranch());}
