  function bindRuleModal(){const type=document.getElementById('rule-type');if(type)type.addEventListener('change',()=>{document.querySelector('.adm-rule-weak').hidden=type.value!=='weakness';});}
  function bindChange(id,fn){const el=document.getElementById(id);if(el)el.addEventListener('change',fn);}
  function afterRender(){
    if(!document.getElementById('admin-classic-css')){const link=document.createElement('link');link.id='admin-classic-css';link.rel='stylesheet';link.href='admin-classic.css';document.head.appendChild(link);}
    document.getElementById('admin-ui-styles')?.remove();
    for(const field of ['branch','department','major','tag','search','joinFrom','joinTo'])bindChange('assign-'+field,()=>{const d=captureAssign();d[field]=val('assign-'+field);if(field==='branch')d.department='all';d.selected=[];D().save();D().go('assign');});
    for(const id of ['adm-content','adm-due','adm-note','adm-notify','adm-reinforcement'])bindChange(id,()=>{captureAssign();D().save();});
    bindChange('tracking-exclude-counters',()=>{state().admin.excludeCounters=checked('tracking-exclude-counters');D().save();D().go('tracking');});
    const map={branch:'branchFilter',department:'departmentFilter',major:'majorFilter',course:'trackingCourse',tag:'tagFilter',search:'trackingSearch',source:'trackingSource',from:'trackingFrom',to:'trackingTo'};
    for(const [field,key]of Object.entries(map))bindChange('tracking-'+field,()=>{state().admin[key]=val('tracking-'+field);if(field==='branch')state().admin.departmentFilter='all';D().save();D().go('tracking');});
    for(const [field,key]of Object.entries({branch:'branchFilter',department:'departmentFilter',major:'majorFilter',tag:'tagFilter',search:'peopleSearch',status:'peopleStatus'}))bindChange('people-'+field,()=>{state().admin[key]=val('people-'+field);if(field==='branch')state().admin.departmentFilter='all';D().save();D().go('people');});
    bindChange('csv-mode',()=>{state().admin.csvMode=val('csv-mode');D().save();});bindChange('csv-line',()=>{state().admin.csvLine=val('csv-line');D().save();});
    const input=document.getElementById('adm-csv-file');if(input)input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;const feedback=document.getElementById('adm-csv-feedback');try{if(file.size>2*1024*1024)throw Error('檔案超過 2 MB，請分批匯入');if(!/\.csv$/i.test(file.name))throw Error('請先另存為 UTF-8 CSV');feedback.textContent='正在本機解析與檢核…';const text=await file.text();if(text.includes('\uFFFD'))throw Error('文字編碼不正確，請另存為 UTF-8 CSV');validateCSV(text,file.name);}catch(e){feedback.textContent=e.message;feedback.classList.add('adm-error');}});
  }
  window.AdminUI={initialize,render,handle,afterRender,parseCSV,validateCSV,scopePeople,scopeCourses,filteredAssignments,weaknessStats,rulePeople,majorFor,isNewcomer,currentCategories,dispatchScore,simulationDate};
